using System.Windows.Forms;

class MainForm : Form
{
    private StatusStrip _statusStrip;

    public MainForm()
    {
        _statusStrip = new StatusStrip();

        // .NET 9 breaking change: StatusStrip default renderer changed from
        // Professional to System. Explicitly set to preserve .NET 8 appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;

        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }
}

using System;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

class MyPropertyEditor : UITypeEditor
{
    public override object? EditValue(
        System.ComponentModel.ITypeDescriptorContext? context,
        IServiceProvider provider,
        object? value)
    {
        var editorService = provider.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService is null)
            return value;

        // .NET 9 breaking change: DropDownControl now throws ArgumentNullException
        // if the control argument is null. Always guard against null before calling.
        var control = CreateEditorControl(value);
        if (control is not null)
        {
            editorService.DropDownControl(control);
            value = GetValueFromControl(control);
        }

        return value;
    }

    private Control? CreateEditorControl(object? currentValue)
    {
        var listBox = new ListBox();
        listBox.Items.AddRange(new object[] { "Option A", "Option B", "Option C" });
        return listBox;
    }

    private object? GetValueFromControl(Control control)
    {
        if (control is ListBox lb && lb.SelectedItem is not null)
            return lb.SelectedItem;
        return null;
    }
}

